-- Test-only owner helpers expose fixture revisions within this rollback transaction.
create function pg_temp.access_revision(target uuid) returns bigint language sql security definer set search_path='' as $$ select p.access_revision from public.profiles p where p.id=target and p.id::text like 'd1000000-%' $$;
create function pg_temp.assignment_revision(org uuid,target uuid,staff boolean) returns bigint language sql security definer set search_path='' as $$ select s.revision from public.staff_organization_assignments s where staff and s.organization_id=org and s.staff_user_id=target union all select a.revision from public.organization_admin_assignments a where not staff and a.organization_id=org and a.admin_user_id=target $$;
